<?php require 'includes/db.php';$title='IT Assets';
if(isset($_GET['delete'])){$s=$conn->prepare("DELETE FROM assets WHERE id=?");$s->bind_param('i',$_GET['delete']);$s->execute();header('Location: assets.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$s=$conn->prepare("INSERT INTO assets(asset_tag,asset_type,brand,model,serial_number,employee_id,purchase_date,status) VALUES(?,?,?,?,?,?,?,?)");$e=$_POST['employee_id']===''?null:(int)$_POST['employee_id'];$s->bind_param('sssssiss',$_POST['asset_tag'],$_POST['asset_type'],$_POST['brand'],$_POST['model'],$_POST['serial_number'],$e,$_POST['purchase_date'],$_POST['status']);$s->execute();header('Location: assets.php');exit;}
$emps=$conn->query("SELECT id,name FROM employees ORDER BY name");$rows=$conn->query("SELECT a.*,e.name employee FROM assets a LEFT JOIN employees e ON e.id=a.employee_id ORDER BY a.id DESC");require 'includes/header.php';?>
<div class="toolbar"><div><h2>Asset Inventory</h2><p>Track laptops, monitors and company equipment.</p></div><button class="btn" onclick="add.showModal()">+ Add Asset</button></div><section class="panel"><table><tr><th>Asset Tag</th><th>Type</th><th>Device</th><th>Assigned To</th><th>Status</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><b><?=htmlspecialchars($r['asset_tag'])?></b><br><small><?=htmlspecialchars($r['serial_number']??'')?></small></td><td><?=htmlspecialchars($r['asset_type'])?></td><td><?=htmlspecialchars(($r['brand']??'').' '.($r['model']??''))?></td><td><?=htmlspecialchars($r['employee']??'Available')?></td><td><em><?=htmlspecialchars($r['status'])?></em></td><td><a class="danger" href="?delete=<?=$r['id']?>" onclick="return confirm('Delete asset?')">Delete</a></td></tr><?php endwhile;?></table></section>
<dialog id="add"><form method="post"><h3>Add IT Asset <button type="button" onclick="add.close()">×</button></h3><div class="grid"><label>Asset Tag<input name="asset_tag" placeholder="LAP-003" required></label><label>Type<input name="asset_type" placeholder="Laptop" required></label><label>Brand<input name="brand"></label><label>Model<input name="model"></label><label>Serial Number<input name="serial_number"></label><label>Employee<select name="employee_id"><option value="">Available</option><?php while($e=$emps->fetch_assoc()):?><option value="<?=$e['id']?>"><?=htmlspecialchars($e['name'])?></option><?php endwhile;?></select></label><label>Purchase Date<input name="purchase_date" type="date"></label><label>Status<select name="status"><option>Available</option><option>Assigned</option><option>Repair</option><option>Retired</option></select></label></div><button class="btn">Save Asset</button></form></dialog><?php require 'includes/footer.php';?>